package com.papaya.claims.claim.domain;

import java.time.Instant;
import java.math.BigDecimal;
import java.util.Objects;
import java.util.UUID;

public record Claim(UUID id, String memberId, String state, BigDecimal policyLimit, String currency,
                    long version, ClaimFacts facts,
                    Instant createdAt, Instant updatedAt) {
    public Claim {
        Objects.requireNonNull(id, "id");
        if (memberId == null || memberId.isBlank()) throw new IllegalArgumentException("Member id is required");
        if (state == null || state.isBlank()) throw new IllegalArgumentException("Claim state is required");
        Objects.requireNonNull(policyLimit, "policyLimit");
        if (policyLimit.signum() < 0 || policyLimit.scale() > 2
                || policyLimit.precision() - policyLimit.scale() > 16) {
            throw new IllegalArgumentException("Policy limit must be nonnegative and fit numeric(18,2)");
        }
        if (currency == null || !currency.matches("[A-Z]{3}")) {
            throw new IllegalArgumentException("Currency must be a three-letter uppercase code");
        }
        if (version < 0) throw new IllegalArgumentException("Claim version cannot be negative");
        Objects.requireNonNull(facts, "facts");
        Objects.requireNonNull(createdAt, "createdAt");
        Objects.requireNonNull(updatedAt, "updatedAt");
    }
}

public record ClaimView(UUID id, String state, BigDecimal policyLimit, String currency,
                        long version, Map<String, Object> facts,
                        Instant createdAt, Instant updatedAt) {
    public ClaimView {
        Objects.requireNonNull(id, "id");
        if (state == null || state.isBlank()) throw new IllegalArgumentException("Claim state is required");
        Objects.requireNonNull(policyLimit, "policyLimit");
        if (policyLimit.signum() < 0 || policyLimit.scale() > 2
                || policyLimit.precision() - policyLimit.scale() > 16) {
            throw new IllegalArgumentException("Policy limit must be nonnegative and fit numeric(18,2)");
        }
        if (currency == null || !currency.matches("[A-Z]{3}")) throw new IllegalArgumentException("Currency is invalid");
        if (version < 0) throw new IllegalArgumentException("Claim version cannot be negative");
        facts = new ClaimFacts(Objects.requireNonNull(facts, "facts")).values();
        Objects.requireNonNull(createdAt, "createdAt");
        Objects.requireNonNull(updatedAt, "updatedAt");
    }

package com.papaya.claims.claim.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;
import jakarta.validation.constraints.Digits;
import java.math.BigDecimal;
import java.util.Map;

public record CreateClaimRequest(@NotNull @PositiveOrZero @Digits(integer = 16, fraction = 2) BigDecimal policyLimit,
                                 @NotBlank @Pattern(regexp = "[A-Z]{3}") String currency,
                                 @NotNull @Size(max = 100) Map<String, Object> facts) { }
package com.papaya.claims.claim.api.dto;

import com.papaya.claims.claim.domain.TransitionResult;
import java.util.Objects;

/** HTTP representation of a persisted or replayed transition outcome. */
public record TransitionResultView(ClaimView claim, AuditEntryView audit, boolean replayed) {
    public TransitionResultView {
        Objects.requireNonNull(claim, "claim");
        Objects.requireNonNull(audit, "audit");
    }

    public static TransitionResultView from(TransitionResult result) {
        Objects.requireNonNull(result, "result");
        return new TransitionResultView(ClaimView.from(result.claim()), AuditEntryView.from(result.audit()), result.replayed());
    }
}
