package com.papaya.claims.workflow;

import java.util.List;

public final class WorkflowEngine {
    private final WorkflowDefinition definition;
    private final GuardEvaluator guards;
    private final EffectRegistry effects;

    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards) {
        this(definition, guards, new EffectRegistry());
    }

    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards, EffectRegistry effects) {
        this.definition = definition;
        this.guards = guards;
        this.effects = effects;
        if (!effects.strategyIds().containsAll(definition.effects().keySet()))
            throw new IllegalArgumentException("Workflow definition contains an unregistered effect strategy");
    }
    public List<WorkflowOption> available(WorkflowEvaluationContext c) {
        return definition.transitions().stream().filter(t -> t.from().equals(c.claim().state())).map(t -> {
            List<String> failures = failures(t, c);
            return new WorkflowOption(t.id(), t.from(), t.to(), t.roles(), failures.isEmpty(), failures, t.effects());
        }).toList();
    }
    public WorkflowDecision evaluate(WorkflowEvaluationContext c) {
        List<WorkflowOption> opts=available(c); WorkflowDefinition.Transition t=definition.transitions().stream().filter(x->x.from().equals(c.claim().state())&&x.to().equals(c.command().targetState())).findFirst().orElse(null);
        if(t==null) {
            String choices = opts.stream().map(option -> option.transitionId() + " -> " + option.to())
                    .collect(java.util.stream.Collectors.joining(", "));
            String message = "No configured transition from " + c.claim().state() + " to "
                    + c.command().targetState() + ". Available transitions: " + (choices.isEmpty() ? "none" : choices);
            return new WorkflowDecision(false, null, c.claim().state(), c.command().targetState(),
                    "INVALID_EDGE", message, List.of(), opts);
        }
        if(!t.roles().stream().anyMatch(c.actor()::hasRole)) return WorkflowDecision.denied("ROLE_FORBIDDEN","Actor is not authorized for this transition",opts);
        for(String g:t.guards()) if(!guards.passes(g,c)) return WorkflowDecision.denied(g.toUpperCase(java.util.Locale.ROOT),definition.guardMessages().get(g),opts);
        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
        if(t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter())>=cycle.maximum())
            return WorkflowDecision.denied("CYCLE_LIMIT",cycle.errorMessage(),opts);
        List<EffectIntent> plannedEffects = t.effects().stream().map(id -> effects.resolve(id, c)).toList();
        return new WorkflowDecision(true,t.id(),t.from(),t.to(),null,null,plannedEffects,opts);
    }
    private List<String> failures(WorkflowDefinition.Transition t, WorkflowEvaluationContext c) {
        List<String> failures = new java.util.ArrayList<>();
        if (t.roles().stream().noneMatch(c.actor()::hasRole)) failures.add("ROLE_FORBIDDEN");
        for (String guard : t.guards()) if (!guards.passes(guard, c)) failures.add(guard);
        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
        if (t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter()) >= cycle.maximum()) failures.add("CYCLE_LIMIT");
        return List.copyOf(failures);
    }
}
package com.papaya.claims.workflow;

import com.papaya.claims.claim.domain.Actor;
import com.papaya.claims.claim.domain.Claim;
import com.papaya.claims.claim.domain.TransitionCommand;
import java.time.Duration;
import java.time.Instant;
import java.util.Objects;

public record WorkflowEvaluationContext(Claim claim, Actor actor, TransitionCommand command,
        WorkflowEvidence evidence, Instant now, Duration appealPeriod) {
    public WorkflowEvaluationContext {
        Objects.requireNonNull(claim); Objects.requireNonNull(actor); Objects.requireNonNull(command);
        Objects.requireNonNull(evidence); now = Objects.requireNonNull(now).truncatedTo(java.time.temporal.ChronoUnit.MICROS);
        Objects.requireNonNull(appealPeriod);
        if (appealPeriod.isNegative() || appealPeriod.isZero()) throw new IllegalArgumentException("Appeal period must be positive");
    }
}
package com.papaya.claims.workflow;

import java.time.Instant;

/** Trusted server supplied evidence. Never construct this record from client supplied facts. */
public record WorkflowEvidence(int informationRequests, Instant lastInformationRequestedAt,
        Instant lastInformationReceivedAt, Instant assessmentStartedAt, Instant rejectedAt,
        Instant memberAcknowledgedRejectionAt, boolean paymentRequestExists, String paymentReference,
        Instant paymentConfirmedAt) {
    public WorkflowEvidence {
        lastInformationRequestedAt = micros(lastInformationRequestedAt);
        lastInformationReceivedAt = micros(lastInformationReceivedAt);
        assessmentStartedAt = micros(assessmentStartedAt);
        paymentConfirmedAt = micros(paymentConfirmedAt);
        rejectedAt = micros(rejectedAt);
        memberAcknowledgedRejectionAt = micros(memberAcknowledgedRejectionAt);
        if (informationRequests < 0) throw new IllegalArgumentException("Cycle count cannot be negative");
    }
    public int counterValue(String counter) {
        if ("informationRequests".equals(counter)) return informationRequests;
        throw new IllegalArgumentException("Unsupported cycle counter: " + counter);
    }
    private static Instant micros(Instant value) { return value == null ? null : value.truncatedTo(java.time.temporal.ChronoUnit.MICROS); }
    public static WorkflowEvidence empty() { return new WorkflowEvidence(0,null,null,null,null,null,false,null,null); }
}
package com.papaya.claims.workflow;

import java.util.List;

public record WorkflowDecision(boolean allowed, String transitionId, String from, String to,
                               String failureCode, String failureMessage, List<EffectIntent> effects,
                               List<WorkflowOption> availableTransitions) {
    public WorkflowDecision { effects = List.copyOf(effects); availableTransitions = List.copyOf(availableTransitions); }
    public static WorkflowDecision denied(String code, String message, List<WorkflowOption> available) {
        return new WorkflowDecision(false, null, null, null, code, message, List.of(), available);
    }
}
workflow:
  version: challenge-14-v1
  initial-state: SUBMITTED
  information-cycle-limit: 3
  cycle-policy:
    transition-id: request-information
    counter: informationRequests
    maximum: 3
    error-message: Maximum information requests exceeded — escalate to team lead
  states:
    - SUBMITTED
    - DOCUMENTS_VERIFIED
    - UNDER_ASSESSMENT
    - PENDING_INFO
    - APPROVED
    - REJECTED
    - PAYMENT_INITIATED
    - CLOSED
  guard-catalog:
    all_required_documents_present:
      failure-message: All required documents must be present and valid before verification.
    assessor_assigned:
      failure-message: An assessor must be assigned before assessment can start.
    assessment_report_complete:
      failure-message: A complete assessment report is required before a decision.
    amount_within_policy_limit:
      failure-message: The requested amount must be nonnegative and no greater than the policy limit.
    rejection_reason_present:
      failure-message: A rejection reason is required.
    information_description_present:
      failure-message: A description of the missing information is required.
    new_information_received:
      failure-message: New information must be received before returning to verification.
    payment_request_exists:
      failure-message: A persisted payment request is required before payment initiation.
    payment_confirmed:
      failure-message: Payment must be confirmed with a reference before closure.
    appeal_period_expired_or_member_acknowledged:
      failure-message: The appeal period must expire or the member must acknowledge the rejection.
  effect-catalog:
    notify_assessor_team: Log a notification to the assessor team.
    record_assessment_start: Record the assessment start time.
    notify_member_approval: Log an approval notification to the member.
    create_payment_request: Persist a payment request.
    notify_member_rejection: Log the reason and appeal instructions for the member.
    notify_information_request: Log the requested information for the member.
    reset_assessment_timer: Reset the assessment timer and clear stale completion data.
    trigger_payment_system: Add a payment dispatch request to the local outbox.
    notify_member_payment_reference: Log the confirmed payment reference to the member.
    archive_claim: Archive the rejected claim after the appeal condition is met.
  transitions:
    - id: verify-documents
      from: SUBMITTED
      to: DOCUMENTS_VERIFIED
      authorized-roles: [document_clerk]
      guards: [all_required_documents_present]
      effects: [notify_assessor_team]
    - id: start-assessment
      from: DOCUMENTS_VERIFIED
      to: UNDER_ASSESSMENT
      authorized-roles: [team_lead]
      guards: [assessor_assigned]
      effects: [record_assessment_start]
    - id: approve-claim
      from: UNDER_ASSESSMENT
      to: APPROVED
      authorized-roles: [assessor]
      guards: [assessment_report_complete, amount_within_policy_limit]
      effects: [notify_member_approval, create_payment_request]
    - id: reject-claim
      from: UNDER_ASSESSMENT
      to: REJECTED
      authorized-roles: [assessor]
      guards: [assessment_report_complete, rejection_reason_present]
      effects: [notify_member_rejection]
    - id: request-information
      from: UNDER_ASSESSMENT
      to: PENDING_INFO
      authorized-roles: [assessor]
      guards: [information_description_present]
      effects: [notify_information_request]
    - id: return-with-information
      from: PENDING_INFO
      to: DOCUMENTS_VERIFIED
      authorized-roles: [document_clerk]
      guards: [new_information_received]
      effects: [reset_assessment_timer]
    - id: initiate-payment
      from: APPROVED
      to: PAYMENT_INITIATED
      authorized-roles: [finance]
      guards: [payment_request_exists]
      effects: [trigger_payment_system]
    - id: close-paid-claim
      from: PAYMENT_INITIATED
      to: CLOSED
      authorized-roles: [finance]
      guards: [payment_confirmed]
      effects: [notify_member_payment_reference]
    - id: close-rejected-claim
      from: REJECTED
      to: CLOSED
      authorized-roles: [system]
      guards: [appeal_period_expired_or_member_acknowledged]
      effects: [archive_claim]
