      properties:
        claim: { $ref: '#/components/schemas/Claim' }
        audit: { $ref: '#/components/schemas/AuditEntry' }
        replayed: { type: boolean }
  responses:
    Error:
      description: Stable error envelope
      content:
        application/json:
          schema:
            type: object
            required: [code, message, correlationId]
            properties:
              code: { type: string }
              message: { type: string }
              details: { type: array, items: { type: string } }
              correlationId: { type: string }
