+    private final EffectsMapper mapper; private final ObjectMapper json;
+    public MyBatisOutboxRepository(EffectsMapper mapper,ObjectMapper json) { this.mapper=mapper; this.json=json; }
+    @Override public void enqueue(Message m) {
+        OutboxRow r=new OutboxRow(); r.id=m.id(); r.claimId=m.claimId(); r.effect=m.effect(); r.payloadJson=m.payload();
