@Aspect
@Component
public class ClaimFailureAuditAspect {
    private static final Logger log = LoggerFactory.getLogger(ClaimFailureAuditAspect.class);
    private final FailureAuditWriter writer;
    public ClaimFailureAuditAspect(FailureAuditWriter writer) { this.writer = writer; }

    @AfterThrowing(pointcut = "execution(* com.papaya.claims.claim.service.ClaimServiceImpl.create(..)) || "
            + "execution(* com.papaya.claims.claim.service.ClaimServiceImpl.updateFacts(..)) || "
            + "execution(* com.papaya.claims.claim.service.ClaimServiceImpl.acknowledgeRejection(..)) || "
