        Fixture fixture = new Fixture("UNDER_ASSESSMENT", "member-1", Map.of("assessorId", "assessor-1"), ClaimWorkflowData.empty());
        assertThatThrownBy(() -> fixture.service.updateFacts(CLAIM_ID,
