            patch.write_text("diff --git a/src/main/java/example/App.java b/src/main/java/example/App.java\n--- a/src/main/java/example/App.java\n+++ b/src/main/java/example/App.java\n@@ -1 +1 @@\n-a\n+b\n", encoding="utf-8")
