package com.papaya.claims.claim.domain.persistence;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.catchThrowable;

import com.papaya.claims.claim.domain.IdempotencyRepository.Receipt;
import java.util.UUID;
import org.junit.jupiter.api.Test;

class IdempotencyIT extends PersistenceITSupport {
    @Test
    void repositoryRoundTripsReceiptAndPropagatesUniqueConflict() {
        String fingerprint="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
        String result="{\"claimId\":\""+UUID.randomUUID()+"\",\"state\":\"approved\",\"version\":7}";
        Receipt receipt=new Receipt(UUID.randomUUID(),"actor-1","claim.transition","request-1",fingerprint,result);
        try(var s=session()) {
            var repo=idempotencyRepository(s); repo.insert(receipt);
            assertThat(repo.find("actor-1","claim.transition","request-1")).contains(receipt);
            assertThat(catchThrowable(()->repo.insert(new Receipt(UUID.randomUUID(),"actor-1","claim.transition","request-1","different-fingerprint","{}")))).isNotNull();
            assertThat(repo.find("actor-1","claim.transition","request-1")).contains(receipt);
        }
    }
}
package com.papaya.claims.claim.domain.persistence;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.papaya.claims.claim.domain.IdempotencyRepository;
import com.papaya.claims.claim.domain.mapper.ReceiptMapper;
import java.util.Optional;
import org.springframework.stereotype.Repository;

@Repository
public class MyBatisIdempotencyRepository implements IdempotencyRepository {
    private final ReceiptMapper mapper; private final ObjectMapper json;
    public MyBatisIdempotencyRepository(ReceiptMapper mapper,ObjectMapper json) { this.mapper=mapper; this.json=json; }
    @Override public void lock(String actor, String scope, String key) { mapper.lock(actor, scope, key); }
    @Override public Optional<Receipt> find(String actor,String scope,String key) {
        ReceiptRow r=mapper.find(actor,scope,key);
        if(r==null) return Optional.empty();
        return Optional.of(new Receipt(r.id,r.actorId,r.scope,r.idempotencyKey,r.fingerprint,r.resultJson));
    }
    @Override public void insert(Receipt receipt) {
        ReceiptRow r=new ReceiptRow(); r.id=receipt.id(); r.actorId=receipt.actorId(); r.scope=receipt.scope();
        r.idempotencyKey=receipt.idempotencyKey(); r.fingerprint=receipt.fingerprint(); r.resultJson=receipt.resultJson();
        mapper.insert(r); // Unique(actor,scope,key) violations propagate for service-level race/replay handling.
    }
}
package com.papaya.claims.claim.domain.persistence;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.papaya.claims.claim.domain.*;
import java.util.Map;

final class PersistenceMapping {
    private static final TypeReference<Map<String,Object>> MAP = new TypeReference<>() {};
    private PersistenceMapping() {}
    static String json(ObjectMapper mapper, Object value) {
        try { return mapper.writeValueAsString(value); }
        catch (JsonProcessingException e) { throw new IllegalArgumentException("Could not encode persistence JSON", e); }
    }
    static Map<String,Object> map(ObjectMapper mapper, String value) {
        try { return mapper.readValue(value, MAP); }
        catch (JsonProcessingException e) { throw new IllegalStateException("Could not decode persisted JSON", e); }
    }
    static ClaimAggregate aggregate(ObjectMapper mapper, ClaimRow r) {
        Claim c = new Claim(r.id, r.memberId, r.state, r.policyLimit, r.currency, r.version,
                new ClaimFacts(map(mapper, r.factsJson)), r.createdAt, r.updatedAt);
        return new ClaimAggregate(c, new ClaimWorkflowData(r.informationRequests, r.lastInformationRequestedAt,
                r.lastInformationReceivedAt, r.assessmentStartedAt, r.rejectedAt, r.memberAcknowledgedRejectionAt));
    }
    static ClaimRow row(ObjectMapper mapper, ClaimAggregate a) {
        Claim c = a.claim(); ClaimWorkflowData w = a.workflow(); ClaimRow r = new ClaimRow();
        r.id=c.id(); r.memberId=c.memberId(); r.state=c.state(); r.policyLimit=c.policyLimit(); r.currency=c.currency();
        r.version=c.version(); r.factsJson=json(mapper,c.facts().values()); r.informationRequests=w.informationRequests();
        r.lastInformationRequestedAt=w.lastInformationRequestedAt(); r.lastInformationReceivedAt=w.lastInformationReceivedAt();
        r.assessmentStartedAt=w.assessmentStartedAt(); r.rejectedAt=w.rejectedAt();
        r.memberAcknowledgedRejectionAt=w.memberAcknowledgedRejectionAt(); r.createdAt=c.createdAt(); r.updatedAt=c.updatedAt(); return r;
    }
}

