package com.papaya.claims.common.web;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.papaya.claims.claim.api.dto.ApiError;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import jakarta.servlet.http.HttpServletResponse;
import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Component
@Order(Ordered.HIGHEST_PRECEDENCE + 1)
public class JsonRequestSizeFilter extends OncePerRequestFilter {
    public static final int MAX_BYTES = 65_536;
    private final ObjectMapper json;
    public JsonRequestSizeFilter(ObjectMapper json) { this.json = json; }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String type = request.getContentType();
        if (!request.getRequestURI().startsWith("/api/") || type == null
                || !type.toLowerCase(java.util.Locale.ROOT).startsWith(MediaType.APPLICATION_JSON_VALUE)) {
            chain.doFilter(request, response); return;
        }
        byte[] body = request.getInputStream().readNBytes(MAX_BYTES + 1);
        if (body.length > MAX_BYTES) {
            response.setStatus(413); response.setContentType(MediaType.APPLICATION_JSON_VALUE);
            json.writeValue(response.getOutputStream(), new ApiError("REQUEST_TOO_LARGE", "JSON request body exceeds 65536 bytes",
                    List.of(), CorrelationIdFilter.currentId(request)));
            return;
        }
        chain.doFilter(new CachedBodyRequest(request, body), response);
    }

    private static final class CachedBodyRequest extends HttpServletRequestWrapper {
        private final byte[] body;
        CachedBodyRequest(HttpServletRequest request, byte[] body) { super(request); this.body = body; }
        @Override public ServletInputStream getInputStream() {
            ByteArrayInputStream input = new ByteArrayInputStream(body);
            return new ServletInputStream() {
                @Override public int read() { return input.read(); }
                @Override public boolean isFinished() { return input.available() == 0; }
                @Override public boolean isReady() { return true; }
                @Override public void setReadListener(ReadListener listener) { throw new UnsupportedOperationException("Async request bodies are not supported"); }
            };
        }
        @Override public BufferedReader getReader() { return new BufferedReader(new InputStreamReader(getInputStream(), StandardCharsets.UTF_8)); }
        @Override public int getContentLength() { return body.length; }
        @Override public long getContentLengthLong() { return body.length; }
    }
}
package com.papaya.claims.security;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.crypto.factory.PasswordEncoderFactories;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;
import com.fasterxml.jackson.databind.ObjectMapper;

@Configuration
@EnableWebSecurity
public class SecurityConfiguration {
    @Bean
    PasswordEncoder passwordEncoder() { return PasswordEncoderFactories.createDelegatingPasswordEncoder(); }

    @Bean
    InMemoryUserDetailsManager users(PasswordEncoder encoder,
            @Value("${claims.security.demo-password:}") String humanPassword,
            @Value("${claims.security.system-password:}") String systemPassword) {
        requireConfiguredSecret(humanPassword, "CLAIMS_DEMO_PASSWORD");
        requireConfiguredSecret(systemPassword, "CLAIMS_SYSTEM_PASSWORD");
        return new InMemoryUserDetailsManager(
                User.withUsername("clerk").password(encoder.encode(humanPassword)).roles("DOCUMENT_CLERK").build(),
                User.withUsername("lead").password(encoder.encode(humanPassword)).roles("TEAM_LEAD").build(),
                User.withUsername("assessor").password(encoder.encode(humanPassword)).roles("ASSESSOR").build(),
                User.withUsername("finance").password(encoder.encode(humanPassword)).roles("FINANCE").build(),
                User.withUsername("member-demo").password(encoder.encode(humanPassword)).roles("MEMBER").build(),
                User.withUsername("system").password(encoder.encode(systemPassword)).roles("SYSTEM").build());
    }

    @Bean
    SecurityFilterChain security(HttpSecurity http, ObjectMapper json) throws Exception {
        return http
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/", "/index.html", "/styles.css", "/app.js", "/favicon.ico", "/actuator/health", "/v3/api-docs/**", "/swagger-ui/**").permitAll()
                        .anyRequest().authenticated())
                .httpBasic(Customizer.withDefaults())
                .csrf(Customizer.withDefaults())
                .exceptionHandling(errors -> errors.authenticationEntryPoint(new JsonSecurityHandlers(json))
                        .accessDeniedHandler(new JsonSecurityHandlers(json)))
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED))
                .build();
    }

    private static void requireConfiguredSecret(String value, String name) {
        if (value == null || value.isBlank() || value.startsWith("CHANGE_ME_"))
            throw new IllegalStateException(name + " must be configured to start the application");
    }
}
package com.papaya.claims.security;

import com.papaya.claims.claim.domain.Actor;
import java.util.Set;
import java.util.stream.Collectors;
import org.springframework.security.core.Authentication;

/** Builds workflow identity exclusively from the authenticated principal. */
public final class ActorFactory {
    private ActorFactory() { }

    public static Actor from(Authentication authentication) {
        if (authentication == null || !authentication.isAuthenticated()) {
            throw new IllegalArgumentException("Authenticated principal is required");
        }
        String username = authentication.getName();
        Set<String> roles = authentication.getAuthorities().stream()
                .map(a -> a.getAuthority())
                .filter(a -> a.startsWith("ROLE_"))
                .map(a -> a.substring(5).toLowerCase(java.util.Locale.ROOT))
                .collect(Collectors.toUnmodifiableSet());
        boolean system = username.equals("system") && roles.contains("system");
        String actorId = username.startsWith("member-") ? username.substring("member-".length()) : username;
        return new Actor(actorId, roles, system);
    }
}
package com.papaya.claims.audit;

import com.papaya.claims.claim.domain.Actor;
import com.papaya.claims.claim.domain.SystemOperationAuditRecord;
import com.papaya.claims.claim.domain.SystemOperationAuditRepository;
import com.papaya.claims.claim.service.BusinessException;
import java.time.Clock;
import java.time.temporal.ChronoUnit;
import java.util.UUID;
import java.util.regex.Pattern;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/** Records failed mutation attempts in a separate transaction, even when the business transaction rolls back. */
@Service
public class FailureAuditWriter {
    private static final Pattern SAFE_CORRELATION = Pattern.compile("[A-Za-z0-9._:-]{1,128}");
    private final SystemOperationAuditRepository audit;
    private final Clock clock;
    public FailureAuditWriter(SystemOperationAuditRepository audit, Clock clock) { this.audit = audit; this.clock = clock; }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void record(String action, String resource, String resourceId, Actor actor,
            String correlationId, Throwable failure) {
        if (actor == null) return;
        String errorType = failure instanceof BusinessException business ? business.code() : failure.getClass().getSimpleName();
        String safeCorrelation = correlationId != null && SAFE_CORRELATION.matcher(correlationId).matches()
                ? correlationId : UUID.randomUUID().toString();
        audit.append(new SystemOperationAuditRecord(UUID.randomUUID(), action, resource, resourceId,
                actor.id(), safeCorrelation,
                "FAILED", errorType, clock.instant().truncatedTo(ChronoUnit.MICROS)));
    }
}

