@Repository
public class MyBatisPaymentRepository implements PaymentRepository {
    private final EffectsMapper mapper;
    public MyBatisPaymentRepository(EffectsMapper mapper) { this.mapper=mapper; }
    @Override public void create(UUID claimId,UUID requestId,String currency,BigDecimal amount) {
        PaymentRow r=new PaymentRow(); r.claimId=claimId; r.requestId=requestId; r.currency=currency; r.amount=amount; mapper.createPayment(r);
    }
    @Override public boolean exists(UUID claimId) { return mapper.paymentExists(claimId); }
    @Override public Optional<Confirmation> confirmation(UUID claimId) {
        PaymentRow r=mapper.paymentConfirmation(claimId); return r==null ? Optional.empty() : Optional.of(new Confirmation(r.reference,r.confirmedAt));
    }
    @Override public boolean confirm(UUID claimId,String reference) { return mapper.confirmPayment(claimId,reference)==1; }
}
package com.papaya.claims.claim.domain.persistence;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.papaya.claims.claim.domain.IdempotencyRepository;
import com.papaya.claims.claim.domain.mapper.ReceiptMapper;
import java.util.Optional;
import org.springframework.stereotype.Repository;

@Repository
public class MyBatisIdempotencyRepository implements IdempotencyRepository {
    private final ReceiptMapper mapper; private final ObjectMapper json;
    public MyBatisIdempotencyRepository(ReceiptMapper mapper,ObjectMapper json) { this.mapper=mapper; this.json=json; }
    @Override public void lock(String actor, String scope, String key) { mapper.lock(actor, scope, key); }
    @Override public Optional<Receipt> find(String actor,String scope,String key) {
        ReceiptRow r=mapper.find(actor,scope,key);
        if(r==null) return Optional.empty();
        return Optional.of(new Receipt(r.id,r.actorId,r.scope,r.idempotencyKey,r.fingerprint,r.resultJson));
    }
    @Override public void insert(Receipt receipt) {
        ReceiptRow r=new ReceiptRow(); r.id=receipt.id(); r.actorId=receipt.actorId(); r.scope=receipt.scope();
        r.idempotencyKey=receipt.idempotencyKey(); r.fingerprint=receipt.fingerprint(); r.resultJson=receipt.resultJson();
        mapper.insert(r); // Unique(actor,scope,key) violations propagate for service-level race/replay handling.
    }
}
package com.papaya.claims.claim.domain.persistence;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.papaya.claims.claim.domain.OutboxRepository;
import com.papaya.claims.claim.domain.mapper.EffectsMapper;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.springframework.stereotype.Repository;
import org.springframework.beans.factory.annotation.Value;

@Repository
public class MyBatisOutboxRepository implements OutboxRepository {
    private final EffectsMapper mapper; private final long leaseMillis;
    public MyBatisOutboxRepository(EffectsMapper mapper,
            @Value("${claims.outbox.lease-duration-ms:30000}") long leaseMillis) {
        if (leaseMillis < 1) throw new IllegalArgumentException("Outbox lease duration must be positive");
        this.mapper=mapper; this.leaseMillis=leaseMillis;
    }
    @Override public void enqueue(Message m) {
        OutboxRow r=new OutboxRow(); r.id=m.id(); r.claimId=m.claimId(); r.effect=m.effect(); r.payloadJson=m.payload();
        r.attempts=m.attempts(); r.availableAt=m.availableAt(); mapper.enqueue(r);
    }
    @Override public List<Message> claimDue(Instant now,int limit) {
        if(limit<1) throw new IllegalArgumentException("limit must be positive");
        return mapper.claimDue(now,limit,leaseMillis).stream().map(r -> new Message(r.id,r.claimId,r.effect,r.payloadJson,r.attempts,r.availableAt)).toList();
    }
    @Override public boolean markDelivered(UUID id,Instant at) { return mapper.delivered(id,at)==1; }
    @Override public boolean markFailed(UUID id,String safeError,Instant retryAt) { return mapper.failed(id,safeError,retryAt)==1; }
}
package com.papaya.claims.claim.domain.persistence;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.papaya.claims.claim.domain.*;
import com.papaya.claims.claim.domain.mapper.ClaimMapper;
import java.util.Optional;
import org.springframework.stereotype.Repository;

@Repository
public class MyBatisClaimRepository implements ClaimRepository {
    private final ClaimMapper mapper; private final ObjectMapper json;
    public MyBatisClaimRepository(ClaimMapper mapper, ObjectMapper json) { this.mapper=mapper; this.json=json; }
    @Override public void insert(ClaimAggregate claim) { mapper.insert(PersistenceMapping.row(json, claim)); }
    @Override public Optional<ClaimAggregate> find(java.util.UUID id) { return Optional.ofNullable(mapper.find(id)).map(r -> PersistenceMapping.aggregate(json,r)); }
    @Override public Optional<ClaimAggregate> findForUpdate(java.util.UUID id) { return Optional.ofNullable(mapper.findForUpdate(id)).map(r -> PersistenceMapping.aggregate(json,r)); }
    @Override public PageResult<ClaimAggregate> listVisible(PageRequest page, Actor actor) {
        boolean memberScoped = actor.hasRole("member") && !actor.system() && !actor.hasRole("claims_admin");
        var rows = memberScoped ? mapper.pageMember(actor.id(),page.size(),page.offset()) : mapper.pageAll(page.size(),page.offset());
        long total = memberScoped ? mapper.countMember(actor.id()) : mapper.countAll();
        return new PageResult<>(rows.stream().map(r -> PersistenceMapping.aggregate(json,r)).toList(), total, page);
    }
    @Override public boolean compareAndSet(ClaimAggregate claim, long expectedVersion) {
        return mapper.compareAndSet(PersistenceMapping.row(json, claim), expectedVersion) == 1;
    }
}

