package com.papaya.claims.claim.domain.persistence;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.catchThrowable;

import com.papaya.claims.claim.domain.IdempotencyRepository.Receipt;
import java.util.UUID;
import org.junit.jupiter.api.Test;

class IdempotencyIT extends PersistenceITSupport {
    @Test
    void repositoryRoundTripsReceiptAndPropagatesUniqueConflict() throws Exception {
        String fingerprint="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
        String result="{\"claimId\":\""+UUID.randomUUID()+"\",\"state\":\"approved\",\"version\":7}";
        Receipt receipt=new Receipt(UUID.randomUUID(),"actor-1","claim.transition","request-1",fingerprint,result);
        try(var s=session()) {
            var repo=idempotencyRepository(s); repo.insert(receipt);
            var loaded = repo.find("actor-1","claim.transition","request-1").orElseThrow();
            assertThat(loaded.id()).isEqualTo(receipt.id());
            assertThat(loaded.actorId()).isEqualTo(receipt.actorId());
            assertThat(loaded.scope()).isEqualTo(receipt.scope());
            assertThat(loaded.idempotencyKey()).isEqualTo(receipt.idempotencyKey());
            assertThat(loaded.fingerprint()).isEqualTo(receipt.fingerprint());
            assertThat(JSON.readTree(loaded.resultJson())).isEqualTo(JSON.readTree(receipt.resultJson()));
            assertThat(catchThrowable(()->repo.insert(new Receipt(UUID.randomUUID(),"actor-1","claim.transition","request-1","different-fingerprint","{}")))).isNotNull();
            assertThat(repo.find("actor-1","claim.transition","request-1")).contains(loaded);
        }
    }
}
package com.papaya.claims.claim.domain.persistence;

import static org.assertj.core.api.Assertions.assertThat;

import com.papaya.claims.claim.domain.OutboxRepository.Message;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;
import org.junit.jupiter.api.Test;

class PaymentOutboxIT extends PersistenceITSupport {
    @Test
    void paymentRepositoryCreatesChecksAndConfirmsPayment() throws Exception {
        UUID claimId=rawClaim(); UUID request=UUID.randomUUID();
        try(var s=session()) {
            var payments=paymentRepository(s);
            payments.create(claimId,request,"USD",new BigDecimal("125.00"));
            assertThat(payments.exists(claimId)).isTrue();
            assertThat(payments.confirm(claimId,"PAY-123")).isTrue();
            var confirmation=payments.confirmation(claimId).orElseThrow();
            assertThat(confirmation.reference()).isEqualTo("PAY-123"); assertThat(confirmation.confirmedAt()).isNotNull();
            assertThat(payments.confirm(claimId,"PAY-456")).isFalse();
        }
    }

    @Test
    void outboxRepositoryUsesConfiguredLeaseAndSupportsRetryAndDelivery() throws Exception {
        UUID claimId=rawClaim(); UUID id=UUID.randomUUID(); Instant now=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);
        try(var s=session()) {
            var outbox=outboxRepository(s,5000);
            outbox.enqueue(new Message(id,claimId,"notify","{\"event\":\"ready\"}",0,now));
            var claimed=outbox.claimDue(now.plusMillis(1),10);
            assertThat(claimed).hasSize(1);
            assertThat(claimed.get(0).id()).isEqualTo(id);
            assertThat(claimed.get(0).attempts()).isEqualTo(1);
            assertThat(claimed.get(0).availableAt()).isAfter(now.plusMillis(4000));
            Instant retry=now.plusSeconds(10);
            assertThat(outbox.markFailed(id,"temporary delivery failure",retry)).isTrue();
            var retried=outbox.claimDue(retry,10);
            assertThat(retried).hasSize(1); assertThat(retried.get(0).attempts()).isEqualTo(2);
            assertThat(outbox.markDelivered(id,retry.plusSeconds(1))).isTrue();
            assertThat(outbox.claimDue(retry.plusSeconds(2),10)).isEmpty();
        }
    }
}
package com.papaya.claims.claim.domain.persistence;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.catchThrowable;

import com.papaya.claims.claim.domain.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.junit.jupiter.api.Test;

class ClaimPersistenceIT extends PersistenceITSupport {
    @Test
    void migrationOwnsSchemaAndRuntimeCannotCreateObjects() throws Exception {
        try (var c=runtime(); var s=c.createStatement(); var r=s.executeQuery("SELECT rolname,rolsuper,rolcreatedb,rolcreaterole FROM pg_roles WHERE rolname IN ('claims_migration','claims_runtime') ORDER BY rolname")) {
            assertThat(r.next()).isTrue(); assertThat(r.getString(1)).isEqualTo("claims_migration");
            assertThat(r.getBoolean(2)).isFalse(); assertThat(r.getBoolean(3)).isFalse(); assertThat(r.getBoolean(4)).isFalse();
            assertThat(r.next()).isTrue(); assertThat(r.getString(1)).isEqualTo("claims_runtime");
            assertThat(r.getBoolean(2)).isFalse(); assertThat(r.getBoolean(3)).isFalse(); assertThat(r.getBoolean(4)).isFalse(); assertThat(r.next()).isFalse();
        }
        try (var c=runtime(); var s=c.createStatement(); var r=s.executeQuery("SELECT has_schema_privilege('claims_migration','public','CREATE'),has_schema_privilege('claims_runtime','public','USAGE'),has_schema_privilege('claims_runtime','public','CREATE')")) {
            assertThat(r.next()).isTrue(); assertThat(r.getBoolean(1)).isTrue(); assertThat(r.getBoolean(2)).isTrue(); assertThat(r.getBoolean(3)).isFalse();
        }
        try (var c=runtime(); var s=c.createStatement(); var r=s.executeQuery("SELECT has_column_privilege('claims_runtime','claims','member_id','UPDATE'),has_column_privilege('claims_runtime','claims','policy_limit','UPDATE'),has_column_privilege('claims_runtime','claims','currency','UPDATE'),has_column_privilege('claims_runtime','claims','state','UPDATE')")) {
            assertThat(r.next()).isTrue(); assertThat(r.getBoolean(1)).isFalse(); assertThat(r.getBoolean(2)).isFalse(); assertThat(r.getBoolean(3)).isFalse(); assertThat(r.getBoolean(4)).isTrue();
        }
        try (var c=runtime(); var s=c.createStatement()) {
            assertThat(catchThrowable(() -> s.execute("CREATE TABLE runtime_must_not_create(id integer)"))).isNotNull();
        }
    }

    @Test
    void repositoryRoundTripListsAndCasLeaveImmutableIdentityAndCoverageUntouched() {
        UUID id=UUID.randomUUID(); Instant now=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);
        BigDecimal nested=new BigDecimal("42.375");
        ClaimAggregate original=new ClaimAggregate(new Claim(id,"member-1","submitted",new BigDecimal("125.00"),"USD",0,
                new ClaimFacts(Map.of("nested",Map.of("amount",nested))),now,now),ClaimWorkflowData.empty());
        try (var s=session()) {
            var repo=claimRepository(s); repo.insert(original);
            ClaimAggregate found=repo.find(id).orElseThrow();
            assertThat(found.claim().facts().values().get("nested")).isInstanceOf(Map.class);
            Object actual=((Map<?,?>)found.claim().facts().values().get("nested")).get("amount");
            assertThat(actual).isInstanceOf(BigDecimal.class).isEqualTo(nested);
            assertThat(found.claim().memberId()).isEqualTo("member-1");
            assertThat(found.claim().policyLimit()).isEqualByComparingTo("125.00");
            assertThat(found.claim().currency()).isEqualTo("USD");
            assertThat(repo.listVisible(new PageRequest(0,10),new Actor("member-1",Set.of("member"),false)).items()).extracting(a->a.claim().id()).contains(id);
            ClaimAggregate attempted=new ClaimAggregate(new Claim(id,"attacker","assessing",new BigDecimal("1.00"),"EUR",0,
                    new ClaimFacts(Map.of("changed",true)),now,now),ClaimWorkflowData.empty());
            assertThat(repo.compareAndSet(attempted,0)).isTrue();
            Claim unchanged=repo.find(id).orElseThrow().claim();
            assertThat(unchanged.state()).isEqualTo("assessing");
            assertThat(unchanged.memberId()).isEqualTo("member-1");
            assertThat(unchanged.policyLimit()).isEqualByComparingTo("125.00");
            assertThat(unchanged.currency()).isEqualTo("USD");
            assertThat(repo.compareAndSet(attempted,0)).isFalse();
        }
    }
}
package com.papaya.claims.claim.domain;

import java.util.Optional;
import java.util.UUID;

/** Persistence port. Mutating methods participate in the application transaction. */
public interface ClaimRepository {
    void insert(ClaimAggregate claim);
    Optional<ClaimAggregate> find(UUID claimId);
    Optional<ClaimAggregate> findForUpdate(UUID claimId);
    PageResult<ClaimAggregate> listVisible(PageRequest page, Actor actor);
    boolean compareAndSet(ClaimAggregate claim, long expectedVersion);
}
package com.papaya.claims.claim.domain;

import java.util.Optional;
import java.util.UUID;

/** Idempotency receipts are inserted in the same transaction as their command. */
public interface IdempotencyRepository {
    /** Serialize concurrent uses of one actor/scope/key within the current transaction. */
    void lock(String actorId, String scope, String key);
    Optional<Receipt> find(String actorId, String scope, String key);
    void insert(Receipt receipt);
    record Receipt(UUID id, String actorId, String scope, String idempotencyKey, String fingerprint, String resultJson) { }
}

