package com.papaya.claims.claim.effects;

import com.papaya.claims.claim.domain.OutboxRepository;
import com.papaya.claims.common.web.Traceparent;
import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.Scope;
import io.micrometer.core.instrument.MeterRegistry;
import java.time.Clock;
import java.time.Duration;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
public class OutboxDispatcher {
    private static final Logger log = LoggerFactory.getLogger(OutboxDispatcher.class);
    private final OutboxRepository outbox;
    private final EffectDelivery delivery;
    private final Clock clock;
    private final Duration retryDelay;
    private final int batchSize;
    private final MeterRegistry metrics;
    private final OpenTelemetry openTelemetry;

    @Autowired
    public OutboxDispatcher(OutboxRepository outbox, EffectDelivery delivery, Clock clock, MeterRegistry metrics,
            OpenTelemetry openTelemetry,
            @Value("${claims.outbox.retry-delay-ms:5000}") long retryDelayMs,
            @Value("${claims.outbox.batch-size:32}") int batchSize) {
        if (retryDelayMs < 1 || batchSize < 1) throw new IllegalArgumentException("Outbox retry delay and batch size must be positive");
        this.outbox = outbox; this.delivery = delivery; this.clock = clock;
        this.retryDelay = Duration.ofMillis(retryDelayMs); this.batchSize = batchSize; this.metrics = metrics;
        this.openTelemetry = openTelemetry;
    }

    public OutboxDispatcher(OutboxRepository outbox, EffectDelivery delivery, Clock clock, MeterRegistry metrics,
            long retryDelayMs, int batchSize) {
        this(outbox, delivery, clock, metrics, OpenTelemetry.noop(), retryDelayMs, batchSize);
    }

    private void deliverWithTrace(OutboxRepository.Message message) {
        Context parent = Traceparent.parent(message.traceparent()).orElse(null);
        if (parent == null) {
            delivery.deliver(message);
            return;
        }
        Span span = openTelemetry.getTracer("claims-workflow-outbox")
                .spanBuilder("claims.outbox.delivery")
                .setParent(parent)
                .setAttribute("claims.outbox.effect", message.effect())
                .startSpan();
        try (Scope ignored = span.makeCurrent()) {
            delivery.deliver(message);
        } catch (RuntimeException failure) {
            span.recordException(failure);
            span.setStatus(StatusCode.ERROR);
            throw failure;
        } finally {
            span.end();
        }
    }

    @Scheduled(fixedDelayString = "${claims.outbox.poll-interval-ms:1000}")
    @Transactional
    public void dispatchDue() {
        List<OutboxRepository.Message> batch = outbox.claimDue(clock.instant(), batchSize);
        for (OutboxRepository.Message message : batch) {
            try {
                deliverWithTrace(message);
                if (outbox.markDelivered(message.id(), clock.instant())) {
                    metrics.counter("claims.outbox.delivered", "effect", message.effect()).increment();
                }
            } catch (RuntimeException failure) {
                outbox.markFailed(message.id(), failure.getClass().getSimpleName(), clock.instant().plus(retryDelay));
                metrics.counter("claims.outbox.failed", "effect", message.effect()).increment();
                log.warn("mock_effect_delivery_failed eventId={} effect={} exceptionType={}",
                        message.id(), message.effect(), failure.getClass().getSimpleName());
            }
        }
    }
}
#!/usr/bin/env python3
"""Exercise the authenticated HTTP claim lifecycle without printing credentials or payloads."""

from __future__ import annotations

import base64
import http.cookiejar
import json
import os
from datetime import datetime, timezone
import sys
import time
import urllib.error
import urllib.request
import uuid
from pathlib import Path


def read_env(path: Path) -> dict[str, str]:
    values: dict[str, str] = {}
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        values[key.strip()] = value.strip()
    return values


class Api:
    def __init__(self, base: str, passwords: dict[str, str], evidence_path: Path):
        self.base = base.rstrip("/")
        self.passwords = passwords
        self.evidence_path = evidence_path
        self.cookies = http.cookiejar.CookieJar()
        self.opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(self.cookies))

    def call(self, username: str | None, method: str, path: str, *, body=None, key=None, csrf=None, traceparent=None):
        correlation_id = "accept-" + uuid.uuid4().hex[:24]
        headers = {"Accept": "application/json", "X-Correlation-ID": correlation_id}
        if body is not None:
            headers["Content-Type"] = "application/json"
        if key:
            headers["Idempotency-Key"] = key
        if traceparent:
            headers["traceparent"] = traceparent
        if csrf:
            headers[csrf["csrfHeaderName"]] = csrf["csrfToken"]
        if username:
            auth = base64.b64encode(f"{username}:{self.passwords[username]}".encode()).decode()
            headers["Authorization"] = f"Basic {auth}"
        data = json.dumps(body, separators=(",", ":")).encode() if body is not None else None
        request = urllib.request.Request(self.base + path, data=data, headers=headers, method=method)
        started = datetime.now(timezone.utc).isoformat()
        try:
            with self.opener.open(request, timeout=10) as response:
                content = response.read()
                result = (response.status, json.loads(content) if content else None, response.headers)
        except urllib.error.HTTPError as error:
            content = error.read()
            try:
                parsed = json.loads(content) if content else None
            except json.JSONDecodeError:
                parsed = None
            result = (error.code, parsed, error.headers)
        record = {
            "timestamp_utc": started, "request": {"method": method, "path": path,
                "headers": {k: ("[REDACTED]" if k.lower() in {"authorization", "x-csrf-token"} or "csrf" in k.lower() else v)
                            for k, v in headers.items()}, "body": body},
            "response": {"status": result[0], "headers": {"X-Correlation-ID": result[2].get("X-Correlation-ID")},
                         "body": result[1]}}
        with self.evidence_path.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(record, separators=(",", ":"), default=str) + "\n")
        return result


def main() -> int:
    env_path = Path(os.environ.get("CLAIMS_ENV_FILE", ".env"))
    if not env_path.is_file():
        print("Missing .env; run bash scripts/setup.sh first.", file=sys.stderr)
        return 2
    env = read_env(env_path)
    required = ("CLAIMS_DEMO_PASSWORD", "CLAIMS_SYSTEM_PASSWORD")
    if any(not env.get(name) or env[name].startswith("CHANGE_ME_") for name in required):
        print("Configured credentials are missing or still placeholders.", file=sys.stderr)
        return 2

    port = env.get("SERVER_PORT", "8080")
    evidence_dir = Path(os.environ.get("CLAIMS_EVIDENCE_DIR", "reports/verification/acceptance-matrix"))
    evidence_dir.mkdir(parents=True, exist_ok=True)
    evidence_path = evidence_dir / "http-exchanges.jsonl"
    evidence_path.unlink(missing_ok=True)
    api = Api(os.environ.get("CLAIMS_API_BASE", f"http://127.0.0.1:{port}"), {
        "clerk": env["CLAIMS_DEMO_PASSWORD"], "lead": env["CLAIMS_DEMO_PASSWORD"],
        "assessor": env["CLAIMS_DEMO_PASSWORD"], "finance": env["CLAIMS_DEMO_PASSWORD"],
        "member-demo": env["CLAIMS_DEMO_PASSWORD"], "system": env["CLAIMS_SYSTEM_PASSWORD"],
    }, evidence_path)
    total = 29
    case = 0
    run_tag = uuid.uuid4().hex
    session_trace_id = uuid.uuid4().hex
    session_parent_span_id = uuid.uuid4().hex[:16]
    approval_trace_id = uuid.uuid4().hex
