        Optional<TransitionResult> replay = replay(actor.id(), scope, key, fingerprint, TransitionResult.class);
        if (replay.isPresent()) {
            TransitionResult result = replay.get();
            return new TransitionResult(result.claim(), result.audit(), true);
        }
