package com.papaya.claims.common.web;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import io.micrometer.observation.ObservationRegistry;
import org.junit.jupiter.api.Test;
import org.slf4j.MDC;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

class CorrelationIdFilterTest {
    @Test
    void preservesOnlyBoundedSafeIdsAndReturnsTheEffectiveCorrelationId() throws Exception {
        var filter = new CorrelationIdFilter(ObservationRegistry.create());
        var request = new MockHttpServletRequest("GET", "/api/v1/claims");
        request.addHeader("X-Correlation-ID", "client:trace-17");
        var response = new MockHttpServletResponse();
        filter.doFilter(request, response, (req, res) -> assertThat(MDC.get("correlationId")).isEqualTo("client:trace-17"));
        assertThat(response.getHeader("X-Correlation-ID")).isEqualTo("client:trace-17");
        assertThat(MDC.get("correlationId")).isNull();
    }

    @Test
    void replacesMalformedOrOversizedIdsWithGeneratedUuid() throws Exception {
        var filter = new CorrelationIdFilter(ObservationRegistry.create());
        var request = new MockHttpServletRequest("GET", "/api/v1/claims");
        request.addHeader("X-Correlation-ID", "bad value");
        var response = new MockHttpServletResponse();
        filter.doFilter(request, response, (req, res) -> { });
        String effective = response.getHeader("X-Correlation-ID");
        assertThat(effective).matches("[0-9a-f-]{36}");
    }

    @Test
    void removesMdcAndStopsObservationWhenDownstreamFails() throws Exception {
        var filter = new CorrelationIdFilter(ObservationRegistry.create());
        var request = new MockHttpServletRequest("POST", "/api/v1/claims");
        request.addHeader("X-Correlation-ID", "valid-17");
        var response = new MockHttpServletResponse();
        assertThatThrownBy(() -> filter.doFilter(request, response, (req, res) -> {
            throw new java.io.IOException("downstream failed");
        })).isInstanceOf(java.io.IOException.class).hasMessage("downstream failed");
        assertThat(MDC.get("correlationId")).isNull();
        assertThat(response.getHeader("X-Correlation-ID")).isEqualTo("valid-17");
        assertThatThrownBy(() -> filter.doFilter(new MockHttpServletRequest("GET", "/api/v1/claims"),
                new MockHttpServletResponse(), (req, res) -> { throw new IllegalStateException("downstream runtime failure"); }))
                .isInstanceOf(IllegalStateException.class).hasMessage("downstream runtime failure");
        assertThat(MDC.get("correlationId")).isNull();
    }

    @Test
    void currentIdUsesExistingRequestAttributeAndGeneratesWhenAbsent() {
        var request = new MockHttpServletRequest();
        assertThat(CorrelationIdFilter.currentId(request)).matches("[0-9a-f-]{36}");
        request.setAttribute(CorrelationIdFilter.ATTRIBUTE, "trusted-id");
        assertThat(CorrelationIdFilter.currentId(request)).isEqualTo("trusted-id");
        request.setAttribute(CorrelationIdFilter.ATTRIBUTE, 4);
        assertThat(CorrelationIdFilter.currentId(request)).matches("[0-9a-f-]{36}");
    }
}

package com.papaya.claims.common.web;

import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanContext;
import io.opentelemetry.api.trace.TraceFlags;
import io.opentelemetry.api.trace.TraceState;
import io.opentelemetry.context.Context;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Converts active W3C trace context to/from the durable local-outbox carrier. */
public final class Traceparent {
    private static final Pattern FORMAT = Pattern.compile("00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})");
    private Traceparent() { }

    public static String current() {
        SpanContext context = Span.current().getSpanContext();
        if (!context.isValid()) return null;
        return "00-" + context.getTraceId() + "-" + context.getSpanId() + "-" + context.getTraceFlags().asHex();
    }

    public static Optional<Context> parent(String value) {
        if (value == null) return Optional.empty();
        Matcher matcher = FORMAT.matcher(value);
        if (!matcher.matches()) return Optional.empty();
        SpanContext parsed = SpanContext.createFromRemoteParent(matcher.group(1), matcher.group(2),
                TraceFlags.fromHex(matcher.group(3), 0), TraceState.getDefault());
        return parsed.isValid() ? Optional.of(Context.root().with(Span.wrap(parsed))) : Optional.empty();
    }
}
package com.papaya.claims.common.web;

import static org.assertj.core.api.Assertions.assertThat;

import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanContext;
import io.opentelemetry.api.trace.TraceFlags;
import io.opentelemetry.api.trace.TraceState;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.Scope;
import org.junit.jupiter.api.Test;

class TraceparentTest {
    private static final String TRACE = "0123456789abcdef0123456789abcdef";
    private static final String PARENT = "0123456789abcdef";

    @Test
    void capturesAndRestoresW3cTraceContext() {
        SpanContext remote = SpanContext.createFromRemoteParent(TRACE, PARENT, TraceFlags.getSampled(), TraceState.getDefault());
        try (Scope ignored = Context.root().with(Span.wrap(remote)).makeCurrent()) {
            String value = Traceparent.current();
            assertThat(value).isEqualTo("00-" + TRACE + "-" + PARENT + "-01");
            Context restored = Traceparent.parent(value).orElseThrow();
            assertThat(Span.fromContext(restored).getSpanContext().getTraceId()).isEqualTo(TRACE);
            assertThat(Span.fromContext(restored).getSpanContext().getSpanId()).isEqualTo(PARENT);
        }
    }

    @Test
    void ignoresAbsentMalformedUnsupportedAndInvalidTraceparents() {
        assertThat(Traceparent.current()).isNull();
        assertThat(Traceparent.parent(null)).isEmpty();
        assertThat(Traceparent.parent("not-a-traceparent")).isEmpty();
        assertThat(Traceparent.parent("01-" + TRACE + "-" + PARENT + "-01")).isEmpty();
        assertThat(Traceparent.parent("00-00000000000000000000000000000000-" + PARENT + "-01")).isEmpty();
    }
}

