    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U \"$${POSTGRES_USER}\" -d \"$${POSTGRES_DB}\""]
      interval: 5s
      timeout: 3s
      retries: 20
      start_period: 10s

  app:
    build:
      context: ..
      dockerfile: docker/Dockerfile
    restart: unless-stopped
    depends_on:
      database:
        condition: service_healthy
      otel-collector:
        condition: service_started
    environment:
      CLAIMS_DATABASE_URL: ${CLAIMS_DATABASE_URL:?Set CLAIMS_DATABASE_URL in .env}
      CLAIMS_RUNTIME_DB_USER: claims_runtime
