package com.papaya.claims.workflow;

import java.math.BigDecimal;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.Set;
import java.util.function.Predicate;

public final class GuardEvaluator {
    private static final Pattern DOCUMENT_ID = Pattern.compile("[A-Za-z0-9][A-Za-z0-9._:-]{0,119}");
    private final Map<String, Predicate<WorkflowEvaluationContext>> strategies = Map.ofEntries(
            Map.entry("all_required_documents_present", this::allRequiredDocumentsPresent),
            Map.entry("assessor_assigned", c -> nonblank(c.claim().facts().values().get("assessorId"))),
            Map.entry("assessment_report_complete", c -> reportComplete(c.claim().facts().values().get("assessmentReport"))),
            Map.entry("amount_within_policy_limit", c -> amountWithin(
                    c.claim().facts().values().get("requestedAmount"), c.claim().policyLimit())),
            Map.entry("rejection_reason_present", c -> nonblank(c.command().reason())),
            Map.entry("information_description_present", c -> nonblank(c.command().reason())),
            Map.entry("new_information_received", this::newInformationReceived),
            Map.entry("payment_request_exists", c -> c.evidence().paymentRequestExists()),
            Map.entry("payment_confirmed", this::paymentConfirmed),
            Map.entry("appeal_period_expired_or_member_acknowledged", this::appealResolved));

    public Set<String> strategyIds() {
        return strategies.keySet();
    }

    public boolean passes(String id, WorkflowEvaluationContext c) {
        Predicate<WorkflowEvaluationContext> strategy = strategies.get(id);
        return strategy != null && strategy.test(c);
    }

    private boolean allRequiredDocumentsPresent(WorkflowEvaluationContext context) {
        return documentsValid(context.claim().facts().values());
    }

    private boolean newInformationReceived(WorkflowEvaluationContext context) {
        WorkflowEvidence evidence = context.evidence();
        return evidence.lastInformationRequestedAt() != null && evidence.lastInformationReceivedAt() != null
                && evidence.lastInformationReceivedAt().isAfter(evidence.lastInformationRequestedAt());
    }

    private boolean paymentConfirmed(WorkflowEvaluationContext context) {
        WorkflowEvidence evidence = context.evidence();
        return evidence.paymentRequestExists() && evidence.paymentConfirmedAt() != null
                && nonblank(evidence.paymentReference());
    }

    private boolean appealResolved(WorkflowEvaluationContext context) {
        WorkflowEvidence evidence = context.evidence();
        return evidence.rejectedAt() != null &&
                ((evidence.memberAcknowledgedRejectionAt() != null
                        && !evidence.memberAcknowledgedRejectionAt().isBefore(evidence.rejectedAt()))
                        || !context.now().isBefore(evidence.rejectedAt().plus(context.appealPeriod())));
    }
    private static boolean nonblank(Object o) { return o instanceof String s && !s.isBlank(); }
    private static boolean amountWithin(Object o, BigDecimal limit) {
        if (!(o instanceof BigDecimal b)) return false;
        return b.signum() >= 0 && b.scale() <= 2 && b.precision() - b.scale() <= 16 && b.compareTo(limit) <= 0;
    }
    private static boolean reportComplete(Object raw) {
        if (!(raw instanceof Map<?, ?> report)) return false;
        return Boolean.TRUE.equals(report.get("complete"));
    }
    private static boolean documentsValid(Map<String,Object> f) {
        Object raw=f.get("documents"); if (!(raw instanceof Map<?,?> docs) || docs.isEmpty()) return false;
        boolean hasRequired = false;
        for (var entry:docs.entrySet()) {
            if (!(entry.getKey() instanceof String id) || !DOCUMENT_ID.matcher(id).matches() || !(entry.getValue() instanceof Map<?,?> d)) return false;
            Object required = d.get("required"), present = d.get("present"), valid = d.get("valid");
            if (!(required instanceof Boolean) || !(present instanceof Boolean) || !(valid instanceof Boolean)) return false;
            if (Boolean.TRUE.equals(required)) {
                hasRequired = true;
                if (!Boolean.TRUE.equals(present) || !Boolean.TRUE.equals(valid)) return false;
            }
        }
        return hasRequired;
    }
}
package com.papaya.claims.claim.api;

import com.papaya.claims.claim.api.dto.*;
import com.papaya.claims.claim.domain.*;
import com.papaya.claims.claim.service.ClaimUseCases;
import com.papaya.claims.common.web.CorrelationIdFilter;
import com.papaya.claims.security.ActorFactory;
import jakarta.validation.Valid;
import jakarta.servlet.http.HttpServletRequest;
import java.net.URI;
import java.util.UUID;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping(ClaimController.API_BASE)
public class ClaimController {
    public static final String API_BASE = "/api/v1";
    public static final String CLAIMS = "/claims";
    public static final String ID = "/{claimId}";
    private final ClaimUseCases claims;

    public ClaimController(ClaimUseCases claims) { this.claims = claims; }

    @GetMapping(CLAIMS)
    public PageResponse<ClaimView> list(@RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size, Authentication authentication) {
        PageResult<Claim> result = claims.listVisible(new PageRequest(page, size), ActorFactory.from(authentication));
        return PageResponse.of(result.items().stream().map(ClaimView::from).toList(), result.total(), result.request());
    }

    @PostMapping(CLAIMS)
    public ResponseEntity<ClaimView> create(@Valid @RequestBody CreateClaimRequest request,
            @RequestHeader("Idempotency-Key") String key,
            HttpServletRequest httpRequest,
            Authentication authentication) {
        Claim claim = claims.create(new CreateClaimCommand(request.policyLimit(), request.currency(), new ClaimFacts(request.facts())),
                ActorFactory.from(authentication), key, CorrelationIdFilter.currentId(httpRequest));
        return ResponseEntity.created(URI.create(API_BASE + CLAIMS + "/" + claim.id())).body(ClaimView.from(claim));
    }

    @GetMapping(CLAIMS + ID)
    public ClaimView get(@PathVariable UUID claimId, Authentication authentication) {
        return ClaimView.from(claims.get(claimId, ActorFactory.from(authentication)));
    }

    @GetMapping(CLAIMS + ID + "/transitions")
    public java.util.List<WorkflowOptionView> options(@PathVariable UUID claimId, Authentication authentication) {
        return claims.options(claimId, ActorFactory.from(authentication)).stream().map(WorkflowOptionView::from).toList();
    }

    @PutMapping(CLAIMS + ID + "/facts")
    public ClaimView updateFacts(@PathVariable UUID claimId, @Valid @RequestBody UpdateFactsRequest request,
            @RequestHeader("Idempotency-Key") String key,
            HttpServletRequest httpRequest,
            Authentication authentication) {
        Claim claim = claims.updateFacts(claimId, new UpdateFactsCommand(request.expectedVersion(), new ClaimFacts(request.facts())),
                ActorFactory.from(authentication), key, CorrelationIdFilter.currentId(httpRequest));
        return ClaimView.from(claim);
    }

    @PostMapping(CLAIMS + ID + "/transitions")
    public TransitionResultView transition(@PathVariable UUID claimId, @Valid @RequestBody TransitionRequest request,
            @RequestHeader("Idempotency-Key") String key,
            HttpServletRequest httpRequest,
            Authentication authentication) {
        TransitionCommand command = new TransitionCommand(request.targetState(), request.expectedVersion(), request.reason(), new ClaimFacts(request.facts()));
        return TransitionResultView.from(claims.transition(claimId, command, ActorFactory.from(authentication), key,
                CorrelationIdFilter.currentId(httpRequest)));
    }

    @PostMapping(CLAIMS + ID + "/system-transitions")
    public TransitionResultView systemTransition(@PathVariable UUID claimId, @Valid @RequestBody TransitionRequest request,
            @RequestHeader("Idempotency-Key") String key,
            HttpServletRequest httpRequest,
            Authentication authentication) {
        TransitionCommand command = new TransitionCommand(request.targetState(), request.expectedVersion(), request.reason(), new ClaimFacts(request.facts()));
        return TransitionResultView.from(claims.systemTransition(claimId, command, ActorFactory.from(authentication), key,
                CorrelationIdFilter.currentId(httpRequest)));
    }

    @PostMapping(CLAIMS + ID + "/rejection-acknowledgement")
    public ClaimView acknowledgeRejection(@PathVariable UUID claimId, @Valid @RequestBody AcknowledgeRejectionRequest request,
            @RequestHeader("Idempotency-Key") String key,
            HttpServletRequest httpRequest,
            Authentication authentication) {
        return ClaimView.from(claims.acknowledgeRejection(claimId, request.expectedVersion(),
                ActorFactory.from(authentication), key, CorrelationIdFilter.currentId(httpRequest)));
    }

    @GetMapping(CLAIMS + ID + "/audit")
    public PageResponse<AuditEntryView> audit(@PathVariable UUID claimId, @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size, Authentication authentication) {
        PageResult<AuditRecord> result = claims.audit(claimId, new PageRequest(page, size), ActorFactory.from(authentication));
        return PageResponse.of(result.items().stream().map(AuditEntryView::from).toList(), result.total(), result.request());
    }
}

package com.papaya.claims.claim.service;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
